    void UpdateGameView(){
        if(IsDisposed||Disposing)return;
        if(rfMapButton!=null){rfMapButton.Visible=GameSettings&&profileGame=="rfonlinenext";rfMapButton.Enabled=settings!=null&&!busy;}
        gameSelect.Enabled=!busy&&gameModules.Count>0&&(String.IsNullOrEmpty(deviceId)||deviceAvailable);
        var module=gameModules.Find(m=>Str(m,"id")==chosenGame);bool noGame=String.IsNullOrEmpty(chosenGame)||chosenGame=="—";moduleVersion=module==null?"":Str(module,"version");moduleLabel.Text=module==null?(noGame?"Игра не назначена":"Модуль недоступен"):deviceTabs==null?Str(module,"name")+" · модуль "+moduleVersion:"Модуль "+moduleVersion;
        if(automationHeading!=null){
            automationHeading.Text=(module==null?"Игра":Str(module,"name"))+" · Автоматизация";
            if(automationGame!=chosenGame){
                if(automationHeading.Image!=null){automationHeading.Image.Dispose();automationHeading.Image=null;}
                string file=System.Text.RegularExpressions.Regex.IsMatch(chosenGame??"","^[a-z][a-z0-9_-]{0,40}$")?Path.GetFullPath(Path.Combine(root,"..","pc","assets","bots",chosenGame+".png")):"";
                if(File.Exists(file)){using(var image=Image.FromFile(file))automationHeading.Image=new Bitmap(image,32,32);}
                else{var fallback=DesktopActionIcons.Get("bot","light");if(fallback!=null)automationHeading.Image=new Bitmap(fallback,32,32);}
                automationGame=chosenGame;
            }
        }
        gameSettingsNotice.Text=noGame?"Выберите игру для этого телефона.":chosenGame!=profileGame?"Игра ещё не назначена этому телефону.":profile!=null&&Bool(profile,"assignmentPending")?"Назначено на ПК · ожидает передачи телефону"+(profile.ContainsKey("assignmentError")?" · "+Str(profile,"assignmentError"):""):GameSettings?"":"Настройки этой игры пока недоступны в клиенте.";
        foreach(var check in new[]{farm,recovery,dismantle,rareDismantle,autostart,questMode,skipCutscenes}){bool supported=(check==questMode||check==skipCutscenes)?GameSettings&&profileGame=="vampir":check==autostart?GameSettings:check==farm?GameSettings&&(LordNineSettings||profileGame=="rfonlinenext"):LordNineSettings;check.Visible=supported;check.Enabled=supported&&!busy;}
        if(gameAutomation!=null)gameAutomation.Visible=GameSettings;
        if(deviceTabs!=null)deviceTabs.SetPageAvailable(1,LordNineSettings);
        foreach(var action in actions){bool available=(String.IsNullOrEmpty(deviceId)||deviceAvailable)&&settings!=null&&!busy;string name=action.Text;if(name=="Назначить")available&=module!=null;else if(name=="Скачать / установить"||name=="Обновить")available&=module!=null&&chosenGame==profileGame;else if(name=="Запустить"||name=="Пауза"||name=="Продолжить"||name=="Остановить"||name=="Откат")available&=!String.IsNullOrEmpty(profileGame)&&profileGame!="—";else if(name.Contains("профиль MultiBot")||name.Contains("фарм"))available&=LordNineSettings;else if(name.Contains("настройки"))available&=GameSettings;action.Enabled=available;if(embedded&&!busy)action.Visible=available;}
        if(embeddedFit!=null)embeddedFit();
    }
    async Task AssignGame(){if(String.IsNullOrEmpty(chosenGame))return;if(!gameModules.Exists(m=>Str(m,"id")==chosenGame)){status.Text="Назначение этой игры пока не поддерживается клиентом.";return;}if(dirty){status.Text="Сначала сохраните или отмените изменения текущей игры.";return;}if(chosenGame!=profileGame&&MessageBox.Show(this,"Назначить игру «"+Convert.ToString(gameSelect.SelectedItem)+"» этому телефону? Настройки другой игры не переносятся.","Смена игры",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;await Action("assign",chosenGame);profile=null;await LoadProfile();}
    async Task OpenRfMap(){
        if(!GameSettings||profileGame!="rfonlinenext"||settings==null||busy)return;
        try{using(var editor=new RfMapEditor(Path.GetFullPath(Path.Combine(root,"..","pc","assets","maps","rfonlinenext")),settings)){
            if(editor.ShowDialog(this)!=DialogResult.OK)return;
            settings["farm_map_spots"]=editor.Spots.ToArray();settings["active_farm_map_spot_id"]=editor.ActiveId;dirty=true;await Save();
        }}catch(Exception error){status.Text="Карта Novus недоступна: "+error.Message;}
    }
    static IEnumerable<Control> SnapshotControls(Control parent){foreach(Control control in parent.Controls)yield return control;}
    static string ActionIcon(string text){switch(text){case "Запустить":return "play";case "Пауза":return "pause";case "Продолжить":return "step-forward";case "Остановить":return "square";case "Скачать / установить":return "download";case "Обновить":return "refresh-cw";case "Откат":return "undo-2";case "Статус":return "info";case "Назначить":return "check";default:return null;}}
    void AddAction(Control container,string text,Func<Task> action){var b=new BotButton{Text=text,ActionIconName=ActionIcon(text),AccessibleName=text,Width=142,Height=46,BackColor=Surface,ForeColor=Color.White,FlatStyle=FlatStyle.Flat};if(container is FlowLayoutPanel && ((FlowLayoutPanel)container).FlowDirection==FlowDirection.TopDown){b.Width=294;b.Height=44;}actions.Add(b);container.Controls.Add(b);toolTips.SetToolTip(b,text);buttonCommands[b]=async()=>await Guard(action);b.Click+=(s,e)=>buttonCommands[b]();}
