    void AddMoveRows(Dictionary<string,object> spot,bool chain){
        var map=mapItems.Find(m=>Str(m,"id")==Str(spot,"map_id"));if(map==null)return;string file=Path.Combine(root,"lordnine","maps",Str(map,"image"));if(!File.Exists(file))return;
        var teleport=Arr(spot.ContainsKey("teleport_point")?spot["teleport_point"]:null);var plan=Obj(spot.ContainsKey("travel_plan")?spot["travel_plan"]:null);if(chain&&Str(plan,"type")=="deadmans_district_chain")return;string target=Str(plan,"target_floor");string id=Str(spot,"map_id");int routeRow=id.Contains("3f")||target=="3F"?1:0;
        try{using(var stream=File.OpenRead(file))using(var bitmap=new Bitmap(stream)){for(int i=0;i<MoveRowCenters.Length;i++){
            if(chain&&i!=routeRow)continue;double y=MoveRowCenters[i];var rect=Rectangle.FromLTRB((int)(bitmap.Width*.745),(int)(bitmap.Height*(y-.029)),(int)(bitmap.Width*.955),(int)(bitmap.Height*(y+.029)));var crop=bitmap.Clone(rect,bitmap.PixelFormat);
