            if(!chain&&bright/(double)Math.Max(1,count)<.015&&edges/(double)Math.Max(1,count)<.015){crop.Dispose();continue;}
            int row=i;var button=new MoveRowButton{Image=crop,Width=Math.Max(160,pointList.ClientSize.Width-SystemInformation.VerticalScrollBarWidth-12),AccessibleName=chain?"Переход маршрута · Move #"+(i+1):"Fast Travel "+(i+1),Enabled=!chain,SelectedRow=teleport.Length==2&&Math.Abs(Convert.ToDouble(teleport[0])-(.735+.47*(.986-.735)))<=.030&&Math.Abs(Convert.ToDouble(teleport[1])-y)<=.030,Margin=new Padding(3,3,3,3)};toolTips.SetToolTip(button,button.AccessibleName);button.Click+=(s,e)=>SelectTeleportRow(row);pointList.Controls.Add(button);
        }}}catch{pointList.Controls.Add(new Label{Text="Список Move недоступен",AutoSize=true,ForeColor=Color.Silver});}
