    void StyleList(ListBox list){list.Dock=DockStyle.Fill;list.BorderStyle=BorderStyle.None;list.BackColor=Surface;list.ForeColor=Color.White;list.IntegralHeight=false;list.ItemHeight=28;}
    void LoadMonsters(Dictionary<string,object> location){monsters.Clear();monsterList.Items.Clear();canvas.SelectedMonster=null;if(location.ContainsKey("monster_targets"))foreach(var raw in A(location["monster_targets"])){var m=(Dictionary<string,object>)raw;monsters.Add(m);monsterList.Items.Add("Ур. "+S(m,"level")+" · "+S(m,"label"));}canvas.Monsters=monsters;canvas.Invalidate();}
    void AddMonsterPoint(){if(monsterList.SelectedIndex<0){hint.Text="Выберите монстра слева.";return;}if(Spots.Count>=256){hint.Text="Не более 256 точек.";return;}var m=monsters[monsterList.SelectedIndex];var positions=A(m["positions"]);if(positions.Length==0){hint.Text="Нет координат появления.";return;}var pos=(Dictionary<string,object>)positions[0];if(!Convert.ToBoolean(pos["inside_atlas"])){hint.Text="Позиция вне карты Novus.";return;}Spots.Add(new Dictionary<string,object>{{"id","rf_"+Guid.NewGuid().ToString("N")},{"map_id","novus_world_101"},{"label",S(m,"label")},{"map_points",new object[]{new object[]{pos["x"],pos["y"]}}},{"enabled",true},{"run_after_teleport",false},{"teleport_point",null},{"catalog_location_id",S(m,"location_id")},{"catalog_monster_id",S(m,"id")},{"npc_index",m["npc_index"]},{"target_world_xyz",pos["world_xyz"]}});changed=true;RefreshPoints(Spots.Count-1);}
