    void FilterLocations(){filtered.Clear();locationList.Items.Clear();monsters.Clear();monsterList.Items.Clear();canvas.SelectedLocation=null;canvas.SelectedMonster=null;canvas.Invalidate();foreach(var p in locations){string text=S(p,"label")+(String.IsNullOrEmpty(S(p,"level"))?"":" · "+S(p,"level"));if(text.Replace('ё','е').Replace('Ё','Е').IndexOf(search.Text.Replace('ё','е').Replace('Ё','Е'),StringComparison.OrdinalIgnoreCase)<0)continue;filtered.Add(p);locationList.Items.Add(text);}}
