public sealed class RfMapCanvas : Control {
    public Image Map;public List<Dictionary<string,object>> Locations,Spots,Monsters;
    public string SelectedMonster;
    public bool AddMode,Labels=true;public string SelectedLocation,SelectedPoint;
    public event Action<double,double> AddPoint;
    double scale=1,ox,oy;bool dragging,moved;Point down;double startX,startY;
    public RfMapCanvas(){DoubleBuffered=true;BackColor=Color.FromArgb(13,23,28);TabStop=true;AccessibleName="Карта Novus";Resize+=(s,e)=>{if(!IsHandleCreated)return;Clamp();Invalidate();};}
    double MinScale{get{return Map==null?1:Math.Min(Width/(double)Map.Width,Height/(double)Map.Height);}}
    public void Fit(){scale=MinScale;ox=(Width-Map.Width*scale)/2;oy=(Height-Map.Height*scale)/2;Invalidate();}
    void Clamp(){if(Map==null)return;double w=Map.Width*scale,h=Map.Height*scale;ox=w<Width?(Width-w)/2:Math.Max(Width-w,Math.Min(0,ox));oy=h<Height?(Height-h)/2:Math.Max(Height-h,Math.Min(0,oy));}
    public void ZoomAt(double factor,int x,int y){if(Map==null)return;double old=scale;scale=Math.Max(MinScale,Math.Min(MinScale*12,scale*factor));ox=x-(x-ox)*scale/old;oy=y-(y-oy)*scale/old;Clamp();Invalidate();}
    public void FocusAt(double x,double y){if(Map==null)return;scale=Math.Max(scale,MinScale*4);ox=Width/2-x*Map.Width*scale;oy=Height/2-y*Map.Height*scale;Clamp();Invalidate();}
    public PointF ScreenPoint(double x,double y){return new PointF((float)(ox+x*Map.Width*scale),(float)(oy+y*Map.Height*scale));}
    public double[] MapPoint(Point p){double x=(p.X-ox)/(Map.Width*scale),y=(p.Y-oy)/(Map.Height*scale);return x>=0&&x<1&&y>=0&&y<1?new[]{x,y}:null;}
    protected override void OnMouseWheel(MouseEventArgs e){ZoomAt(e.Delta>0?1.25:.8,e.X,e.Y);base.OnMouseWheel(e);}
    protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);Focus();if(e.Button!=MouseButtons.Left&&e.Button!=MouseButtons.Right)return;dragging=true;moved=false;down=e.Location;startX=ox;startY=oy;Capture=true;}
    protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);if(!dragging)return;if(Math.Abs(e.X-down.X)+Math.Abs(e.Y-down.Y)>5)moved=true;if(moved){ox=startX+e.X-down.X;oy=startY+e.Y-down.Y;Clamp();Invalidate();}}
    protected override void OnMouseUp(MouseEventArgs e){base.OnMouseUp(e);if(!dragging)return;dragging=false;Capture=false;if(e.Button==MouseButtons.Left&&!moved&&AddMode){var p=MapPoint(e.Location);if(p!=null&&AddPoint!=null)AddPoint(p[0],p[1]);}}
    protected override bool ProcessCmdKey(ref Message m,Keys key){if(key==Keys.Home){Fit();return true;}if(key==Keys.Add||key==Keys.Oemplus){ZoomAt(1.25,Width/2,Height/2);return true;}if(key==Keys.Subtract||key==Keys.OemMinus){ZoomAt(.8,Width/2,Height/2);return true;}return base.ProcessCmdKey(ref m,key);}
    protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);if(Map==null)return;e.Graphics.InterpolationMode=InterpolationMode.HighQualityBilinear;e.Graphics.DrawImage(Map,new RectangleF((float)ox,(float)oy,(float)(Map.Width*scale),(float)(Map.Height*scale)));e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;
        var occupied=new List<Rectangle>();if(Locations!=null)foreach(var p in Locations){var at=ScreenPoint(Convert.ToDouble(p["x"]),Convert.ToDouble(p["y"]));if(at.X<0||at.Y<0||at.X>Width||at.Y>Height)continue;string id=Convert.ToString(p["id"]),kind=Convert.ToString(p["kind"]);bool selected=id==SelectedLocation;Color color=kind=="town"?Color.FromArgb(249,199,87):Color.FromArgb(98,231,188);using(var b=new SolidBrush(color))if(kind=="town")e.Graphics.FillPolygon(b,new[]{new PointF(at.X,at.Y-6),new PointF(at.X+6,at.Y),new PointF(at.X,at.Y+6),new PointF(at.X-6,at.Y)});else e.Graphics.FillEllipse(b,at.X-4,at.Y-4,8,8);if(selected)using(var pen=new Pen(Color.White,2))e.Graphics.DrawEllipse(pen,at.X-9,at.Y-9,18,18);
            if(Labels){string text=Convert.ToString(p["label"])+(Convert.ToString(p["level"])==""?"":" · "+Convert.ToString(p["level"]));var size=TextRenderer.MeasureText(text,Font);var rect=new Rectangle((int)at.X+9,(int)at.Y-size.Height/2,size.Width+4,size.Height+4);bool overlap=occupied.Exists(r=>r.IntersectsWith(rect));if(!overlap||selected){using(var brush=new SolidBrush(Color.FromArgb(210,13,23,28)))e.Graphics.FillRectangle(brush,rect);TextRenderer.DrawText(e.Graphics,text,Font,rect,selected?Color.White:color,TextFormatFlags.NoPadding|TextFormatFlags.VerticalCenter);occupied.Add(rect);}}
        }
        if(Monsters!=null)foreach(var monster in Monsters){var positions=monster["positions"] as System.Collections.IList;if(positions==null)continue;foreach(Dictionary<string,object> pos in positions){if(!Convert.ToBoolean(pos["inside_atlas"]))continue;var at=ScreenPoint(Convert.ToDouble(pos["x"]),Convert.ToDouble(pos["y"]));bool selected=Convert.ToString(monster["id"])==SelectedMonster;using(var pen=new Pen(selected?Color.White:Color.FromArgb(190,144,255),selected?3:2)){e.Graphics.DrawLine(pen,at.X-5,at.Y-5,at.X+5,at.Y+5);e.Graphics.DrawLine(pen,at.X-5,at.Y+5,at.X+5,at.Y-5);}if(selected){TextRenderer.DrawText(e.Graphics,Convert.ToString(monster["label"]),Font,new Point((int)at.X+9,(int)at.Y),Color.White,Color.FromArgb(13,23,28));}}}
        if(Spots!=null){int n=0;foreach(var p in Spots){n++;if(Convert.ToString(p["map_id"])!="novus_world_101")continue;var list=p["map_points"] as object[];if(list==null||list.Length==0)continue;var xy=list[0] as object[];if(xy==null||xy.Length!=2)continue;var at=ScreenPoint(Convert.ToDouble(xy[0]),Convert.ToDouble(xy[1]));using(var b=new SolidBrush(Color.FromArgb(255,174,64)))e.Graphics.FillEllipse(b,at.X-11,at.Y-11,22,22);TextRenderer.DrawText(e.Graphics,n.ToString(),Font,new Rectangle((int)at.X-11,(int)at.Y-11,22,22),Color.Black,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.NoPadding);if(Convert.ToString(p["id"])==SelectedPoint)using(var pen=new Pen(Color.White,2))e.Graphics.DrawEllipse(pen,at.X-14,at.Y-14,28,28);}}
    }
    protected override void Dispose(bool disposing){if(disposing&&Map!=null){Map.Dispose();Map=null;}base.Dispose(disposing);}
}

